<script setup>
import {computed,reactive,ref,watch} from 'vue';
import MButton from '../../../components/mds/MButton.vue'; import MDialog from '../../../components/mds/MDialog.vue'; import MInput from '../../../components/mds/MInput.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue'; import MSelect from '../../../components/mds/MSelect.vue';
import {toAdminUserDraft,toAdminUserPayload} from '../domain/admin-user-write.mjs';
const props=defineProps({record:Object,editing:Boolean,saving:Boolean,error:String,roleOptions:{type:Array,default:()=>[]},safeAreaStyle:Object});const emit=defineEmits(['cancel','save']);const draft=reactive({...toAdminUserDraft(props.record)});const discard=ref(false);const localError=ref('');const title=computed(()=>props.editing?'Sửa người dùng':'Thêm người dùng');watch(()=>props.record,(record)=>Object.assign(draft,toAdminUserDraft(record)),{deep:true});const states=[{value:true,label:'Hoạt động'},{value:false,label:'Khóa'}];const notifications=[{value:true,label:'Nhận nhắc'},{value:false,label:'Không nhận nhắc'}];function submit(){try{localError.value='';emit('save',toAdminUserPayload(draft,{editing:props.editing}));}catch(error){localError.value=error.message;}}
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar :title="title" @back="discard=true"><template #actions><MButton variant="link" @click="discard=true">Hủy</MButton></template></MMobileTopBar><main class="min-h-0 flex-1 overflow-y-auto"><div class="mds-mobile-gutter-x space-y-4 py-4"><label v-if="!editing"><span class="mb-1 block text-[13px] font-medium">Tài khoản *</span><MInput v-model="draft.username" autocomplete="username"/></label><label><span class="mb-1 block text-[13px] font-medium">Họ tên *</span><MInput v-model="draft.full_name" autocomplete="name"/></label><label><span class="mb-1 block text-[13px] font-medium">Vai trò *</span><MSelect v-model="draft.role" :options="roleOptions"/></label><label><span class="mb-1 block text-[13px] font-medium">Email</span><MInput v-model="draft.email" type="email" autocomplete="email"/></label><label><span class="mb-1 block text-[13px] font-medium">{{ editing?'Mật khẩu mới':'Mật khẩu *' }}</span><MInput v-model="draft.password" type="password" :placeholder="editing?'Để trống nếu không đổi':''" autocomplete="new-password"/></label><template v-if="editing"><label><span class="mb-1 block text-[13px] font-medium">Trạng thái</span><MSelect v-model="draft.active" :options="states"/></label><label><span class="mb-1 block text-[13px] font-medium">Nhắc việc</span><MSelect v-model="draft.notify_opt_in" :options="notifications"/></label></template><p v-if="error||localError" role="alert" class="rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ error||localError }}</p></div></main><footer class="shrink-0 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-4 pb-[calc(12px+var(--mds-mobile-safe-bottom))] pt-3"><MButton variant="primary" class="w-full" :loading="saving" @click="submit">{{ editing?'Lưu thay đổi':'Tạo người dùng' }}</MButton></footer><MDialog v-model="discard" :title="editing?'Bỏ thay đổi?':'Bỏ người dùng mới?'" type="danger" confirm-text="Bỏ thay đổi" @confirm="emit('cancel')"><p>Thông tin chưa lưu sẽ không được giữ lại.</p></MDialog></section></template>
